import{c as t,Z as e,Q as i,j as l,m as r,o as s}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"满江红·写怀","description":"","frontmatter":{"title":"满江红·写怀","author":"岳飞","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/11.md","filePath":"books/shici/songci/11.md"}'),n={name:"books/shici/songci/11.md"};function u(h,a,c,p,q,d){const o=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="满江红·写怀" tabindex="-1">满江红·写怀 <a class="header-anchor" href="#满江红·写怀" aria-label="Permalink to &quot;满江红·写怀&quot;">​</a></h1><p><strong>[宋] <a href="/authors/yuefei.html">岳飞</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>怒发冲冠，凭栏处、潇潇雨歇。抬望眼，仰天长啸，壮怀激烈。三十功名尘与土，八千里路云和月。莫等闲、白了少年头，空悲切。</p><p>靖康耻，犹未雪。臣子恨，何时灭！驾长车，踏破贺兰山缺。壮志饥餐胡虏肉，笑谈渴饮匈奴血。待从头、收拾旧山河，朝天阙。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>满江红：词牌名</li><li>怒发冲冠：愤怒得头发竖起，顶起帽子，形容极度愤怒</li><li>凭栏：倚靠栏杆</li><li>潇潇：形容雨势急骤</li><li>长啸：大声呼啸</li><li>壮怀：豪壮的胸怀</li><li>三十功名：指自己三十多岁建立的功名</li><li>尘与土：比喻微不足道</li><li>八千里路：指征战路途遥远</li><li>云和月：指披星戴月的艰苦生活</li><li>等闲：轻易，随便</li><li>靖康耻：指靖康二年（1127年）金兵攻破汴京，掳走徽、钦二帝的耻辱</li><li>贺兰山：此处借指金人的老巢</li><li>胡虏、匈奴：均指金兵</li><li>天阙：皇帝的宫殿</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>愤怒得头发竖起顶起帽子，倚靠栏杆处，急骤的秋雨刚刚停歇。抬眼远望，仰天长声呼啸，豪壮的胸怀激昂热烈。三十多岁的功名如同尘土，八千里的征途伴着云和月。不要轻易虚度年华，等到少年头变白，只能空自悲切。</p><p>靖康年间的耻辱，至今还没有洗雪。作为臣子的愤恨，何时才能消灭！驾着战车，踏破贺兰山的缺口。壮志满怀，饿了就吃敌人的肉，谈笑间渴了就喝敌人的血。等到重新收复旧日山河，再向皇帝朝拜报捷。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是岳飞的代表作，表达了词人强烈的爱国热情和收复失地的坚定决心，是中国文学史上最著名的爱国词篇之一。</p><p>上片写词人的壮志和感慨。&quot;怒发冲冠&quot;，开篇就以强烈的情感震撼人心。&quot;凭栏处、潇潇雨歇&quot;，写词人倚栏远眺的情景。&quot;抬望眼，仰天长啸，壮怀激烈&quot;，将词人的豪情壮志表现得淋漓尽致。&quot;三十功名尘与土，八千里路云和月&quot;，写词人对自己功名的淡泊和征战生涯的回顾。&quot;莫等闲、白了少年头，空悲切&quot;，是全词的名句，表达了珍惜时光、及时建功立业的紧迫感。</p><p>下片写收复失地的决心。&quot;靖康耻，犹未雪。臣子恨，何时灭&quot;，直抒胸臆，表达了对国耻的愤恨。&quot;驾长车，踏破贺兰山缺&quot;，写词人收复失地的雄心。&quot;壮志饥餐胡虏肉，笑谈渴饮匈奴血&quot;，以夸张的手法表达了对敌人的仇恨和战斗的决心。&quot;待从头、收拾旧山河，朝天阙&quot;，表达了收复失地、报效朝廷的坚定信念。</p><p>全词气势磅礴，情感激昂，将爱国热情和战斗精神融为一体，成为千古传诵的爱国名篇。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>岳飞</strong>（1103年－1142年），字鹏举，南宋抗金名将，民族英雄。其词仅存三首，但都是气壮山河的爱国佳作。</p><p><a href="/authors/yuefei.html">查看作者详情 →</a></p></blockquote>',18)),s(o)])}const f=t(n,[["render",u]]);export{m as __pageData,f as default};
